806	<script src="scroll/sc-smooth.js"></script>
807	<script>
808	(function(){
809	  'use strict';
810	
811	  var hero      = document.getElementById('hero-section');
812	  var plateCard = document.getElementById('plateCard');
813	  var faceFront = document.getElementById('faceFront');
814	  var faceBack  = document.getElementById('faceBack');
815	
816	  /* ---- grundbilden som token, så att sökvägen står på ETT ställe -------- */
817	  document.documentElement.style.setProperty(
818	    '--ground-img', "url('/tests/alunix-concepts-r3/build/assets/k4-cabin-desk.webp')");
819	
820	  ScrollCraft.mount(document.body);
821	
822	  /* ---- spacern mäts en gång, vid mount (scroll/README.md) ---------------
823	     Rapporterar innerHeight 0 i det ögonblicket blir spann-höjden 0 px, sidan
824	     får ingen scrolltrack och akten avancerar aldrig. En resize får motorn att
825	     mäta om. Skickas när fönstret och typsnitten har landat. */
826	  function relayout(){ dispatchEvent(new Event('resize')); }
827	  addEventListener('load', relayout);
828	  if (document.fonts && document.fonts.ready) document.fonts.ready.then(relayout);
829	
830	  /* ---- vilken sida av kortet som är nåbar -------------------------------
831	     Baksidans länk finns i DOM:en från början men är osynlig tills kortet
832	     vänts. En fokusbar länk som inte syns är ett a11y-fel, så den sidan som
833	     är bortvänd hålls inert. Utan JS är framsidan uppe och baksidan inert. */
834	  var backLive = null;
835	  function setFace(showBack){
836	    if (backLive === showBack) return;
837	    backLive = showBack;
838	    faceBack.inert = !showBack;
839	    faceFront.inert = showBack;
840	    faceBack.setAttribute('aria-hidden', showBack ? 'false' : 'true');
841	    faceFront.setAttribute('aria-hidden', showBack ? 'true' : 'false');
842	  }
843	  setFace(false);
844	
845	  /* ---- will-change bara medan akten rör sig ----------------------------
846	     Ingen per-bildruta-JS driver vändningen: --flip räknas i CSS ur --sc-ps.
847	     Det här är enbart en gränsövergång, rAF-skyddad, med deadband. */
848	  /* Aktens geometri cachas vid mount och vid resize. Progressen räknas ur
849	     scrollY med motorns egen pinnade formel, p = (y - top) / (height - vh), i
850	     stället för att läsa --sc-ps med getComputedStyle varje bildruta.
851	     MÄTT I R2: shimen läser redan getComputedStyle en gång per akt och
852	     bildruta, och sidan har sex akter. En sjunde läsning från sidans egen loop
853	     kostade utan att ge något: de två gränser den här funktionen bevakar
854	     (0 < ps < 1 och ps >= 0,42) tål den lilla skillnaden mellan råvärdet och
855	     det lerpade. Noll stilläsningar per bildruta här nu. */
856	  var actTop = 0, actH = 0;
857	  function measureAct(){
858	    var r = hero.getBoundingClientRect();
859	    actTop = r.top + window.scrollY;
860	    actH = r.height;
861	  }
862	  measureAct();
863	  addEventListener('resize', measureAct, { passive:true });
864	  addEventListener('load', measureAct);
865	
866	  var turning = null, pending = false;
867	  function readState(){
868	    pending = false;
869	    var travel = Math.max(actH - window.innerHeight, 1);
870	    var ps = (window.scrollY - actTop) / travel;
871	    if (ps < 0) ps = 0; else if (ps > 1) ps = 1;
872	    var moving = ps > 0.0005 && ps < 0.9995;
873	    if (moving !== turning){
874	      turning = moving;
875	      hero.classList.toggle('is-turning', moving);
876	    }
877	    /* smoothstep(0.12, 0.72, ps) korsar 0,5 exakt vid ps = 0,42. */
878	    setFace(ps >= 0.42);
879	  }
880	  function schedule(){ if (!pending){ pending = true; requestAnimationFrame(readState); } }
881	  addEventListener('scroll', schedule, { passive:true });
882	  addEventListener('resize', schedule, { passive:true });
883	  schedule();
884	
885	  /* ---- ramarna monteras en dryg skärm i förväg ---------------------------
886	     `loading="lazy"` ensamt lämnar tidpunkten åt webbläsaren. En
887	     IntersectionObserver med rootMargin 100 % sätter src när ramen är ungefär
888	     en skärm bort, så den är laddad när den når vecket men aldrig vid load.
889	     Tre live-ramar monterade vid load är det tyngsta en marknadssida kan göra
890	     mot sig själv (performance.md § 2). Observern kopplar bort sig per ram, så
891	     ingen ram monteras två gånger, och SJÄLVA ramen rörs aldrig efteråt. */
892	  var frames = Array.prototype.slice.call(document.querySelectorAll('iframe[data-src]'));
893	  if (frames.length){
894	    if ('IntersectionObserver' in window){
895	      /* Själva src-skrivningen läggs i en IDLE-lucka, inte i den bildruta där
896	         observern råkar utlösa. MÄTT I R3: att skriva src direkt i callbacken
897	         lade tre enorma toppar mitt i den pinnade akten, tydligt synliga som
898	         isolerade spikar i `frame-times.png` medan resten av kurvan låg platt.
899	         Det är precis "a long task under the thumb IS the jank"
900	         (performance.md § 1). Observern får fortfarande utlösa en dryg skärm i
901	         förväg, så ramen hinner bli klar; det är TIDPUNKTEN för det dyra
902	         arbetet som flyttas, inte förvarningen. Timeouten gör att en sida som
903	         aldrig blir idle ändå monterar ramen. */
904	      var mountFrame = function(f){
905	        f.src = f.getAttribute('data-src');
906	        f.removeAttribute('data-src');
907	      };
908	      var defer = window.requestIdleCallback
909	        ? function(fn){ requestIdleCallback(fn, { timeout: 600 }); }
910	        : function(fn){ setTimeout(fn, 1); };
911	      var io = new IntersectionObserver(function(entries, obs){
912	        for (var i = 0; i < entries.length; i++){
913	          if (!entries[i].isIntersecting) continue;
914	          var f = entries[i].target;
915	          obs.unobserve(f);
916	          defer(mountFrame.bind(null, f));
917	        }
918	      }, { rootMargin: '100% 0px' });
919	      frames.forEach(function(f){ io.observe(f); });
920	
921	      /* En förvärmning i vilan efter `load` provades och FÖRSÄMRADE mätningen
922	         (p95 209 -> 388 ms vid 100:60): proben börjar scrolla direkt efter
923	         load, så förvärmningen krockade med scrollens början i stället för att
924	         hamna i den tysta luckan vid folden. Den skulle troligen hjälpa en
925	         verklig läsare, som står stilla vid folden i flera sekunder, men det
926	         är ett påstående jag inte kan mäta med instrumentet jag har, och då
927	         skeppas det inte. Konfigurationen nedan är den mätt bästa. */
928	    } else {
929	      /* Ingen observer: montera direkt hellre än att lämna tomma ramar. */
930	      frames.forEach(function(f){ f.src = f.getAttribute('data-src'); });
931	    }
932	  }
933	
934	  /* ---- ordscrubben i liggaren -------------------------------------------
935	     Orden delas EN gång vid montering och får sitt index --i och radens
936	     ordantal --n som inline-variabler. Därefter räknar CSS opaciteten ur
937	     --scrub, som i sin tur är en funktion av --sc-ps. Noll skrivningar per
938	     bildruta, och rått --sc-p rörs inte (F-014 punkt 1).
939	     Vilotillståndet före den här funktionen är det färdiga tillståndet, så en
940	     sida utan JS visar liggaren fullt läsbar. */
941	  var giant = document.getElementById('giant-section');
942	  if (giant){
943	    var blocks = giant.querySelectorAll('.scrub-text h3, .scrub-text p');
944	    for (var b = 0; b < blocks.length; b++){
945	      var el = blocks[b];
946	      var words = el.textContent.split(/\s+/).filter(Boolean);
947	      el.textContent = '';
948	      for (var w = 0; w < words.length; w++){
949	        var span = document.createElement('span');
950	        span.className = 'w';
951	        span.style.setProperty('--i', String(w));
952	        span.style.setProperty('--n', String(words.length));
953	        span.textContent = words[w];
954	        el.appendChild(span);
955	        if (w < words.length - 1) el.appendChild(document.createTextNode(' '));
956	      }
957	    }
958	    giant.classList.add('is-scrubbed');
959	  }
960	
961	  /* ---- ?preview= --------------------------------------------------------
962	     Varje läge sätter window.__scFreezeMotion = true. sc-smooth.js läser
963	     flaggan som ett VÄRDE och spårar då det råa värdet exakt, så en skärmbild
964	     visar det formade läget och inte en lerp i flykten. V3b exponerade
965	     __scFreezeMotion som ett funktionspar, vilket shimen inte kan läsa. */
966	  var MODES = { front:0, mid:0.5, back:1 };
967	  var mode = new URLSearchParams(location.search).get('preview');
968	  if (mode){
969	    window.__scFreezeMotion = true;
970	    document.documentElement.setAttribute('data-preview', mode);
971	  }
972	  if (mode && Object.prototype.hasOwnProperty.call(MODES, mode)){
973	    plateCard.style.setProperty('--flip', String(MODES[mode]));
974	    setFace(MODES[mode] >= 0.5);
975	    hero.classList.remove('is-turning');
976	  }
977	  /* Två lägen till, utlovade i BRIEF.md § ?preview=-plan och möjliga först nu
978	     när deras mål finns byggda. De tvingar det FORMADE läget så att en
979	     stillbild visar slutläget och inte en lerp i flykten. */
980	  if (mode === 'ledger' && giant){
981	    giant.style.setProperty('--scrub', '1');
982	    giant.scrollIntoView({ block:'center' });
983	  }
984	  if (mode === 'bleed'){
985	    var fig = document.querySelector('.thesis-figure');
986	    if (fig){ fig.scrollIntoView({ block:'center' }); }
987	  }
988	})();
989	</script>
990	</body>
991	</html>
